阅读以下代码，输出是什么？
```python
class Base:
    def __init__(self):
        self.__items = []
    def add(self, item):
        self.__items.append(item)
    def get(self):
        return self.__items
class Derived(Base):
    def __init__(self):
        super().__init__()
        self.__items = []
    def add(self, item):
        self.__items.append(item.upper())
