在多继承协同设计中，如何确保 super().__init__ 正确传递参数？
```python
class Base:
    def __init__(self, **kwargs):
        pass
class A(Base):
    def __init__(self, a, **kwargs):
        super().__init__(**kwargs)
        self.a = a
class B(Base):
    def __init__(self, b, **kwargs):
        super().__init__(**kwargs)
        self.b = b
class C(A, B):
    def __init__(self, a, b, **kwargs):
        super().__init__(a=a, b=b, **kwargs)
c = C(a=1, b=2)
```

